// Recover only absent88 chart arrangements. Reuse the complete canonical
// edge/plane registry and all actual power-node inverse packets.
#define GFS_PENDING29_PROJECTION_LIBRARY
#include "test_shared_pending29_projection_v1.cpp"
#include <tuple>
namespace {
using RootKey=std::tuple<int,uint64_t,uint64_t>;
struct Family {bool complete=false;uint64_t work=0,count=0;std::vector<S>root;};
struct FamilyProof {uint64_t slot,source,target,chart,face,boundary,kind,complete,windows,index,count;S parameter;char identity[160];};
struct Request {uint64_t slot,source,target,chart,strips,old_windows;int dependent;int kind=0;};
struct ChartWork {Request request;target::ClippedChart chart;};
struct SlotWork {uint64_t slot=0,source=0,target=0;std::vector<ChartWork>work;std::vector<FamilyProof>proofs;std::map<std::string,target::ScalarRoots>cache;uint64_t canonical_bindings=0,canonical_sign_proofs=0,new_internal_jobs=0,new_internal_windows=0,internal_cache_hits=0,constant_proofs=0,power_bindings=0;};
static void save_family(SlotWork&w,int ci,int face,int side,uint64_t kind,const std::string&id,const target::ScalarRoots&r){
 for(size_t j=0;j<std::max(size_t(1),r.root.size());j++){FamilyProof z={};z.slot=w.slot;z.source=w.source;z.target=w.target;z.chart=ci;z.face=face;z.boundary=side;z.kind=kind;z.complete=r.complete;z.windows=r.windows;z.index=r.root.empty()?UINT64_MAX:j;z.count=r.root.size();if(!r.root.empty())z.parameter=r.root[j];need(id.size()<sizeof(z.identity),"full recovery family identity");snprintf(z.identity,sizeof(z.identity),"%s",id.c_str());w.proofs.push_back(z);}
}
static target::ScalarRoots side_roots(const sd::Compiled&m,const std::vector<target::Face>&faces,const std::vector<target::Plane>&planes,const target::ClippedChart&c,int ci,int face,int side,const std::map<RootKey,Family>&canonical,SlotWork&w){
 const auto&chart=c.reference;int dep=c.coordinate.dependent;target::ScalarRoots out;
 auto evaluate=[&](S u){auto j=target::in_axis(faces[face],chart,dep,u,S(side));sd::Jet f(j.v,j.g[1-dep]);f.H[0][0]=j.H[1-dep][1-dep];return f;};
 bool canonical_side=dep==1&&side==(chart.part?1:0);
 if(canonical_side){
  const auto&t=m.base.state->triangle[m.base.source];int other=chart.part?(chart.apex+2)%3:(chart.apex+1)%3,local=-1;
  for(int e=0;e<3;e++)if((t.endpoint[e][0]==chart.apex&&t.endpoint[e][1]==other)||(t.endpoint[e][1]==chart.apex&&t.endpoint[e][0]==other))local=e;
  need(local>=0,"original canonical half-edge identity");int edge=m.base.edge[local].native.poly[1];auto first=std::min(w.target,planes[face].competitor),second=std::max(w.target,planes[face].competitor);RootKey key(edge,first,second);auto it=canonical.find(key);
  std::string id="canonical;"+std::to_string(edge)+";"+std::to_string(first)+";"+std::to_string(second)+";cut="+qs(c.radial_cut);
  if(it!=canonical.end()){
   need(it->second.complete,"retained whole canonical root family complete");
   for(S t0:it->second.root){S u=S(2)*(t.endpoint[local][0]==chart.apex?t0:S(1)-t0)/S(c.radial_cut);if(sf::upper(u)<0||sf::lower(u)>1)continue;need(sf::lower(u)>0&&sf::upper(u)<1,"canonical root at chart endpoint requires exact shared ownership, not snapping");out.root.push_back(u);}
   std::sort(out.root.begin(),out.root.end(),[](S a,S b){return a.n<b.n;});out.complete=true;w.canonical_bindings++;save_family(w,ci,face,side,1,id,out);return out;
  }
  // Work-registry pruning may omit a strictly nonzero entire edge. Permit
  // only one whole-side sign proof; never start a new canonical root solve.
  auto f=evaluate(sf::range(0,1));out.complete=sf::lower(f.v)>0||sf::upper(f.v)<0;w.canonical_sign_proofs++;save_family(w,ci,face,side,2,id,out);need(out.complete,"canonical family absent and whole-side sign unresolved");return out;
 }
 int geometry=dep==1?chart.apex:side==0?3+chart.apex:6+ci;
 std::string id="internal;"+std::to_string(w.source)+";"+std::to_string(w.target)+";"+std::to_string(planes[face].competitor)+";line="+std::to_string(geometry)+";cut="+qs(c.radial_cut);
 auto old=w.cache.find(id);if(old!=w.cache.end()){w.internal_cache_hits++;save_family(w,ci,face,side,4,id,old->second);return old->second;}
 if(dep==0&&side==0){auto f=evaluate(S(Q(.5L)));out.complete=sf::lower(f.v)>0||sf::upper(f.v)<0;w.constant_proofs++;save_family(w,ci,face,side,5,id,out);need(out.complete,"constant apex boundary not strictly separated");}
 else{out=target::scalar_roots(evaluate);w.new_internal_jobs++;w.new_internal_windows+=out.windows;save_family(w,ci,face,side,3,id,out);need(out.complete,out.reason);}
 w.cache.emplace(id,out);return out;
}
static target::ClippedChart recover_chart(const sd::Compiled&m,const std::vector<target::Face>&faces,const std::vector<target::Plane>&planes,const sf::RealBounds&bound,const std::vector<Event29>&nodes,const std::map<RootKey,Family>&canonical,SlotWork&w,const Request&r){
 target::ClippedChart out;try{
  auto chart=sd::charts(m)[r.chart];out.reference=chart;out.coordinate=target::certified_axis(m,chart,faces,planes,bound);
  // Preserve the original geometry-driven radial trim, including its proof.
  if(!out.coordinate.empty&&!out.coordinate.whole&&out.coordinate.dependent<0){auto shape=target::shape_bounds(m);auto ray=target::frame(m,chart,sf::range(0,1));Q cut=1;for(int index:out.coordinate.active){auto cone=target::gradient_cone(faces[index],shape);S derivative;for(int k=0;k<2;k++)derivative=derivative+cone.gradient[k]*ray.D[k];S A=faces[index].vertex[chart.apex];A.e=sf::add(A.e,planes[index].input_offset_radius);if(sf::lower(derivative)>0&&sf::upper(A)<0){Q candidate=sf::quotient(-sf::lower(A),sf::lower(derivative));if(candidate<cut){cut=candidate;out.trim_face=index;out.apex_face=A;out.radial_derivative_lower=sf::lower(derivative);}}}if(cut<1){need(cut>0,"positive recovered original radial trim");out.radial_cut=cut;for(int a=1;a<3;a++)for(int j=0;j<3;j++)chart.vertex[a][j]=chart.vertex[0][j]+S(cut)*(chart.vertex[a][j]-chart.vertex[0][j]);chart.det=chart.det*S(cut)*S(cut);out.reference=chart;out.coordinate=target::certified_axis(m,chart,faces,planes,bound);}}
  const auto&a=out.coordinate;
  if(r.kind){need((r.kind==1&&a.whole&&!a.empty)||(r.kind==2&&a.empty&&!a.whole),"recovered original whole/excluded classification");out.complete=true;snprintf(out.reason,sizeof(out.reason),"original_whole_excluded_reference_metadata_recovered_without_roots");return out;}
  need(!a.empty&&!a.whole&&a.dependent==r.dependent,"recovered original clipped classification and axis");std::vector<S>events={S(0),S(1)};
  for(int index:a.active)for(int boundary=0;boundary<2;boundary++){auto roots=side_roots(m,faces,planes,out,r.chart,index,boundary,canonical,w);events.insert(events.end(),roots.root.begin(),roots.root.end());out.edge_windows+=roots.windows;}
  // All feasible power vertices already have same-input inverse certificates.
  for(const auto&node:nodes)if(node.slot==w.slot&&node.kind==2){need(node.passed,"retained used power-node packet");auto c=target::coordinates(m,chart,node.reference[0],node.reference[1]);if(sf::upper(c.s)<0||sf::lower(c.s)>1||sf::upper(c.t)<0||sf::lower(c.t)>1)continue;S u=a.dependent==1?c.s:c.t;need(sf::lower(u)>0&&sf::upper(u)<1,"power vertex needs shared chart endpoint ownership");events.push_back(u);w.power_bindings++;}
  std::sort(events.begin(),events.end(),[](S a,S b){return a.n<b.n;});
  for(size_t j=0;j+1<events.size();j++){need(sf::upper(events[j])<sf::lower(events[j+1]),"recovered event order without coalescing");S free=(events[j]+events[j+1])/S(2),lo(0),hi(1);int lower=-1,upper=-1;bool empty=false;
   for(int index:a.active){auto left=target::in_axis(faces[index],chart,a.dependent,S(free.n),S(0)),right=target::in_axis(faces[index],chart,a.dependent,S(free.n),S(1));if(sf::upper(left.v)<0&&sf::upper(right.v)<0)continue;if(sf::lower(left.v)>0&&sf::lower(right.v)>0){empty=true;break;}S root=target::graph(faces[index],chart,a,index,S(free.n));out.unresolved_free=free;out.candidate=root;out.unresolved_face=index;out.selected=sf::lower(a.derivative[index])>0?hi:lo;out.selected_face=sf::lower(a.derivative[index])>0?upper:lower;
    if(sf::lower(a.derivative[index])>0){if(sf::upper(root)<sf::lower(hi)){hi=root;upper=index;}else need(sf::lower(root)>sf::upper(hi),"distinct recovered upper graphs");}else{if(sf::lower(root)>sf::upper(lo)){lo=root;lower=index;}else need(sf::upper(root)<sf::lower(lo),"distinct recovered lower graphs");}}
   if(empty||sf::lower(lo)>sf::upper(hi))continue;need(sf::upper(lo)<sf::lower(hi),"positive recovered actual dependent interval");out.strip.push_back({int(r.chart),a.dependent,lower,upper,events[j],events[j+1]});
  }
  need(out.strip.size()==r.strips,"recovered actual strip count equals original retained status");out.complete=true;snprintf(out.reason,sizeof(out.reason),"missing_geometry_recovered_canonical_reuse_internal_only");
 }catch(const std::exception&e){snprintf(out.reason,sizeof(out.reason),"%s",e.what());}return out;
}
static ChartSnapshot snapshot(const SlotWork&w,const ChartWork&v){const auto&c=v.chart;ChartSnapshot z={};z.slot=w.slot;z.source=w.source;z.target=w.target;z.chart=v.request.chart;z.complete=c.complete;z.empty=c.coordinate.empty;z.whole=c.coordinate.whole;z.strips=c.strip.size();z.windows=c.edge_windows;z.dependent=c.coordinate.dependent;z.trim_face=c.trim_face;z.unresolved_face=c.unresolved_face;z.selected_face=c.selected_face;z.reference=c.reference;z.radial_cut=c.radial_cut;z.radial_derivative_lower=c.radial_derivative_lower;z.apex_face=c.apex_face;z.unresolved_free=c.unresolved_free;z.candidate=c.candidate;z.selected=c.selected;for(int a:c.coordinate.active)z.active_mask|=uint64_t(1)<<a;for(size_t a=0;a<c.coordinate.derivative.size();a++)z.derivative[a]=c.coordinate.derivative[a];snprintf(z.reason,sizeof(z.reason),"%s",c.reason);return z;}
}
