 auto nodes=read29<Event29>(std::string(argv[9])+"/actual_reference_events_rank0.bin");need(nodes.size()==109,"all complete used reference events");std::map<int,sd::Compiled>maps;std::vector<SlotWork*>work;for(auto&e:selected){work.push_back(&e.second);if(!maps.count(e.second.source))maps.emplace(e.second.source,sd::compile(f,e.second.source));}
 #pragma omp parallel for schedule(static)
 for(size_t j=0;j<work.size();j++){auto&w=*work[j];const auto&m=maps.at(w.source);std::vector<target::Plane>planes=target::planes(site,w.target);std::vector<target::Face>faces;for(const auto&plane:planes)faces.push_back(target::pullback(m,plane));for(auto&v:w.work)v.chart=recover_chart(m,faces,planes,bound[w.source].real,nodes,canonical,w,v.request);}
 std::vector<ChartSnapshot>charts;std::vector<StripSnapshot>strips;std::vector<FamilyProof>proofs;uint64_t complete=0,cb=0,cs=0,ij=0,iw=0,ih=0,cp=0,pb=0;std::ofstream csv(dest+"/recovered_chart_metadata.csv");csv<<"slot_id,source,target,chart,complete,dependent,radial_cut,expected_strips,stored_strips,old_root_windows_not_replayed,reason\n";
